function cleanTitle(v){return String(v||'').replace(/\\/g,'/').split('/').pop().replace(/\.(epub|mobi|azw3?|pdf|txt|cbz|cbr)$/i,'').trim()||'未命名书籍'}
function pickCol(cols,tests){return cols.find(c=>tests.some(t=>t.test(c.toLowerCase())))}
